async function createChannel(name, clientId, guildId, hidden = false) {
  const url = "https://kanreplication.onrender.com/channels/create?key=ULhrJ4sbZkL4W3zuD6ZS3G3tWoVcGP7auoeQAJodkrWs7JmahFnWAedprPwbYtaoD23aXXvLfhFE6gaTXEFWqmrLZkjiRsasAT8qWo";
  const data = { name, clientId, guildId, hidden };

  try {
    const response = await fetch(url, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(data)
    });

    const json = await response.json();
    return json;

  } catch (err) {
    console.error("Error creating channel:", err);
    return { error: err.message };
  }
}

